@attr.s(cmp=False)
class TestLine(object):
    """
     :param TestPc test_pc: (DEPRECATED, will be removed in 9.0.0) TestPc object class
     :param Optional[Sequence[Union[ClassicalBts, CloudBts]]] gnbs: List of objects of gnb (Next generation NodeB) subclasses
     :param str tl_cloud_topology: Test Line cloud topology string, defaults to `NON_CM` for tls not using Cloud Manager
     :param Optional[Sequence[CloudHosting]] cloud_hostings: List of objects of CloudHosting subclasses
     :param Optional[Sequence[Enb]] enbs: List of objects of enb (evolved NB) subclasses
     :param Optional[Sequence[NB]] nb_objects: List of objects of NB subclasses
     :param Optional[Sequence[Bts2G]] bts2g_objects: List of objects of Bts2G subclasses
     :param Optional[Sequence[UE]] ues: List of objects of UE (User Equipment) subclasses
     :param Optional[Core] core: object of Core subclasses
     :param Optional[Sequence[Pdu]] pdus: List of objects of Pdu (Power Distribution Unit) subclasses
     :param Optional[NMS] nms: object of subclass of NMS (Network Management Support) class
     :param Cbam cbam: Optional[Cbam] (CloudBand Application Manager) class instance object
     :param Optional[Sequence[HardwareController]] hardware_controllers: List of objects of HardwareController subclasses
     :param Optional[ParagonX] paragonx: sync generator
     :param Optional[Caffeine] caffeine: traffic generator
     :param Optional[Sequence[Switch]] switches: List of objects of Switch subclasses
     :param Optional[Attenuator] attenuator: Attenuator subclass.
            If configured attenuator and attenuators both, will use attenuators.
            *Mark deprecated in 8.32.0, to be removed in later major release. Use the attenuators instead*
     :param Optional[Sequence[Attenuator]] attenuators: List of objects of Attenuator subclass
     :param Optional[Sequence[TestPc]] test_pcs: TestPc class objects
     :param Optional[AppServer] appserver: object of AppServer
     :param Optional[Sequence][AppServer] appservers: List of AppServers (first one is default one)
     :param Optional[Sequence[BSC]] bscs: List of BSCs 2G
     :param Optional[Sequence[RNC]] rncs: List of RNCs 3G
     :param Optional[Sequence[ChannelEmulator]] channel_emulators: List of channel emulators
     :param Optional[Sequence[IPHY]] iphys: List of IPHYs
     :param Optional[Sequence[MCS]] mcses: List of objects of MCS subclass
     :param Optional[Velocity] velocity: Velocity object
     ute_testline_configuration section below:
     :param Optional[Dict[str, str]] HW_TYPE_MAPPINGS: mapping of release eNB to HW type
     :param Optional[GROUP_CONFIG] cus: Dict-like of CUS objects
     :param Optional[str] enb_hw_type: 1st eNB HW type
     :param Optional[int] enb_pdu_outlet: 1st eNB PDU port number
     :param Optional[GROUP_CONFIG] fsm: Dict-like of fsm objects
     :param Optional[GROUP_CONFIG] host: Dict-like of host objects
     :param Optional[str] host_ip: 1st host ip address
     :param Optional[GROUP_CONFIG] iphy: Dict-like of iphy objects
     :param Optional[int] iphy_pdu_outlet: 1st iphy PDU port number
     :param Optional[GROUP_CONFIG] los: Dict-like of los objects
     :param Optional[str] pdu_ip: eNB-1 PDU IP address
     :param Optional[str] pdu_type: eNB-1 PDU type
     :param Optional[GROUP_CONFIG] rf: Dict-like of rf objects
     :param Optional[GROUP_CONFIG] rfs: Dict-like of rfs objects
     :param Optional[GROUP_CONFIG] rtg: Dict-like of rtg objects
     :param Optional[str] top_ip: eNB-1 TOP IP address
     :param Optional[TrsSchemas] trs_ips: TRS IPs of 1st eNB-simulator pair
     :param Optional[GROUP_CONFIG] ue: Dict-like of ue objects
     :param Optional[str] vlan_ids: eNB-1 vlan id
     :param Optional[Dict[int, UTE_WMP]] ute_wmp: Dict of UTE_WMP objects
     :param Optional[NADCM] nadcm: object of NADCM class
     :param Optional[NEAT] neat: object of NEAT class
     :param Optional[DCMSpecificUnits] dcm_specific_units: object of DCMSpecificUnits class
     :param Optional[Sequence[RFSwitch]] rf_switches: List of objects of RFSwitch subclasses
     """
    # TODO: change the order of parameters (tl_cloud_topology, then gnbs)
    # TODO: and set tl_cloud topology parameter as mandatory- investigate if needed
    # TODO: remove test_pc parameter as obsolete and leave only test_pcs list.

    test_pc = attr.ib(type=TestPc)
    gnbs = attr.ib(default=None, type=Optional[Sequence[Union[ClassicalBts, CloudBts]]])
    tl_cloud_topology = attr.ib(default='NON_CM', type=Optional[str])
    cloud_hostings = attr.ib(default=None, type=Optional[Sequence[CloudHosting]])
    enbs = attr.ib(default=None, type=Optional[Sequence[Enb]])
    nb_objects = attr.ib(default=None, type=Optional[Sequence[NB]])
    bts2g_objects = attr.ib(default=None, type=Optional[Sequence[Bts2G]])
    ues = attr.ib(default=None, type=Optional[Sequence[UE]])
    core = attr.ib(default=None, type=Optional[Core])
    pdus = attr.ib(default=None, type=Optional[Sequence[Pdu]])
    nms = attr.ib(default=None, type=Optional[NMS])
    cbam = attr.ib(default=None, type=Optional[Cbam])
    hardware_controllers = attr.ib(default=None, type=Optional[Sequence[HardwareController]])
    paragonx = attr.ib(default=None, type=Optional[ParagonX])
    caffeine = attr.ib(default=None, type=Optional[Caffeine])
    switches = attr.ib(default=None, type=Optional[Sequence[Switch]])
    optical_switches = attr.ib(default=None, type=Optional[Sequence[OpticalSwitch]])
    test_pcs = attr.ib(default=None, type=Optional[Sequence[TestPc]])
    attenuator = attr.ib(default=None, type=Optional[Attenuator])
    attenuators = attr.ib(default=None, type=Optional[Sequence[Attenuator]])
    appserver = attr.ib(default=None, type=Optional[AppServer])
    appservers = attr.ib(default=None, type=Optional[Sequence[AppServer]])
    bscs = attr.ib(default=None, type=Optional[Sequence[BSC]])
    rncs = attr.ib(default=None, type=Optional[Sequence[RNC]])
    channel_emulators = attr.ib(default=None, type=Optional[Sequence[ChannelEmulator]])
    iphys = attr.ib(default=None, type=Optional[Sequence[IPHY]])
    mcses = attr.ib(default=None, type=Optional[Sequence[MCS]])
    velocity = attr.ib(default=None, type=Optional[Velocity])
    HW_TYPE_MAPPINGS = attr.ib(default=None, type=Optional[Dict[str, str]])
    cus = attr.ib(default=None, type=Optional[GROUP_CONFIG])
    enb_hw_type = attr.ib(default=None, type=Optional[str])
    enb_pdu_outlet = attr.ib(default=None, type=Optional[int])
    fsm = attr.ib(default=None, type=Optional[GROUP_CONFIG])
    host = attr.ib(default=None, type=Optional[GROUP_CONFIG])
    host_ip = attr.ib(default=None, type=Optional[str])
    iphy = attr.ib(default=None, type=Optional[GROUP_CONFIG])
    iphy_pdu_outlet = attr.ib(default=None, type=Optional[int])
    los = attr.ib(default=None, type=Optional[GROUP_CONFIG])
    pdu_ip = attr.ib(default=None, type=Optional[str])
    pdu_type = attr.ib(default=None, type=Optional[str])
    rf = attr.ib(default=None, type=Optional[GROUP_CONFIG])
    rfs = attr.ib(default=None, type=Optional[GROUP_CONFIG])
    rtg = attr.ib(default=None, type=Optional[GROUP_CONFIG])
    top_ip = attr.ib(default=None, type=Optional[str])
    trs_ips = attr.ib(default=None, type=Optional[TrsSchemas])
    ue = attr.ib(default=None, type=Optional[GROUP_CONFIG])
    vlan_ids = attr.ib(default=None, type=Optional[str])
    ute_wmp = attr.ib(default=attr.Factory(dict), type=Optional[Dict[int, UTE_WMP]])
    neat = attr.ib(default=None, type=Optional[NEAT])
    nadcm = attr.ib(default=None, type=Optional[NADCM])
    mediator = attr.ib(default=None, type=Optional[DCMMiddleware])
    hdbde = attr.ib(default=None, type=Optional[HDBDE])
    iug = attr.ib(default=None, type=Optional[IUG])
    rf_switches = attr.ib(default=None, type=Optional[Sequence[RFSwitch]])

    def __getitem__(self, item):
        # Temporarily added to mimic ute_config behaviour
        if isinstance(item, int):
            return self.ute_wmp[item]
        else:
            raise TypeError("'TestLine' object is not subscriptable")

    def __iter__(self):
        # Temporarily added to mimic ute_config behaviour
        return iter(self.ute_wmp.values())

    def __attrs_post_init__(self):
        self.test_pcs = self._get_test_pcs(self.test_pc, self.test_pcs)
        self.attenuators = self._get_attenuators(self.attenuator, self.attenuators)
        self.appservers = self._get_appservers(self.appserver, self.appservers)
        self._log_tl_config_name()

    def _log_tl_config_name(self):
        calling_frame = inspect.stack()[3]  # had to be changed from inspect.stack()[2] after introducing attrs
        module = inspect.getmodule(calling_frame[0])
        if not module:
            logger.debug("Unable to find the test line name.")
            return
        module_path = module.__file__
        directory_path = os.path.dirname(module_path)
        site_dir_path, test_line_name = os.path.split(directory_path)
        site_name = os.path.basename(site_dir_path)
        if not site_name or not test_line_name:
            logger.debug("Unable to find the test line name")
            return
        test_line_designator = "{}, {}".format(site_name, test_line_name)
        logger.debug("Test line configuration: {}".format(test_line_designator))

    def _get_test_pcs(self, test_pc, test_pcs):
        if test_pcs is None:
            return [test_pc]
        else:
            return test_pcs

    @staticmethod
    def _get_appservers(appserver, appservers):
        if appservers is None:
            return appserver if isinstance(appserver, list) else [appserver]
        else:
            return appservers

    @staticmethod
    def _get_attenuators(attenuator, attenuators):
        if attenuators is None:
            return attenuator if isinstance(attenuator, list) else [attenuator]
        else:
            return attenuators

    @property
    def control_nodes(self):
        if self.gnbs is None:
            return []
        return [gnb.cu.controlNode for gnb in self.gnbs if gnb.cu is not None and gnb.cu.controlNode is not None]
